#!/usr/bin/env node
/**
 * harness-slot-closure.js
 * =============================================================================
 * Closure + SBOM generator for a TaskHive embedded-DSH runtime "slot".
 *
 * The tool was written because the original closure tool that produced
 * `closure.sha256` for earlier slots is NOT present in this checkout, so those
 * artifacts could not be regenerated by the original means. This script defines
 * a NEW, fully specified, reproducible algorithm set and generates the closure,
 * the payload content digest and a real CycloneDX 1.6 SBOM from what is
 * actually installed on disk.
 *
 * ALGORITHMS
 * -----------------------------------------------------------------------------
 * 1. `taskhive-payload-content-graph-v1`   (payload content digest)
 *
 *    Purpose: a content-addressed digest of the shipped payload tree, stable
 *    across machines and repeat runs.
 *
 *    Definition:
 *      - Walk `<slot>/payload` recursively with `fs.lstatSync`. Symlinks and
 *        junctions (`lstatSync().isSymbolicLink() === true` on Windows) are
 *        RECORDED BUT NEVER DESCENDED INTO, so the walk cannot loop and cannot
 *        double-count a package that is reachable both through the `.pnpm`
 *        store and through a top-level link.
 *      - Build one row per entry and sort the rows by the entry's relative
 *        path (POSIX '/', byte-wise comparison). Sorting by path (not by the
 *        whole row string) keeps the ordering independent of the row encoding.
 *      - Row encodings fed to a single streaming sha256, in sorted order:
 *            regular file : "F" NUL relpath NUL size NUL <sha256 of file bytes> LF
 *            directory    : "D" NUL relpath LF
 *            symlink/junc : "L" NUL relpath NUL <normalized link target> LF
 *            other        : "O" NUL relpath NUL size LF
 *        NUL = 0x00, LF = 0x0a. File bytes are hashed by streaming (never read
 *        whole into memory) and are represented by their own sha256 so the
 *        digest stays cheap to recompute and insensitive to row-size limits.
 *      - Digest = lowercase hex sha256 of that byte stream.
 *
 *    Link-target normalization (needed because pnpm store links are absolute
 *    Windows paths): backslashes become '/', a `\\?\` prefix is stripped, and
 *    a target that resolves inside the slot is rewritten as a slot-relative
 *    POSIX path ('./payload/node_modules/.pnpm/...'). Targets that are
 *    relative or that resolve outside the slot are kept verbatim; the walker
 *    counts those separately (`outOfSlotLinkCount`) so a non-portable payload
 *    is visible rather than silently hashed with machine-specific paths.
 *
 * 2. `taskhive-slot-closure-v3-final-path-links`   (slot closure digest)
 *
 *    Purpose: the identity of the whole slot directory.
 *
 *    Definition: identical row/walk/hash rules as (1), but the root is the
 *    slot directory itself instead of `<slot>/payload`, and relative paths are
 *    relative to the slot root.
 *
 *    Excluded paths (root-level names, so the digest is stable across repeat
 *    runs even though this tool rewrites them):
 *        manifest.json, closure.json, sbom.cdx.json, IMMUTABLE
 *    (`manifest.json` is listed as an exclusion because it is a generated,
 *    closure-referencing document owned by the release process; this tool
 *    never writes it.)
 *
 *    SUPERSEDES -- IT DOES NOT REPRODUCE -- `taskhive-harness-closure-v2-final-path-links`.
 *    The v2 tool is not present in this checkout, its exact row encoding and
 *    exclusion set are unknown, and no amount of work here can produce the
 *    same bytes by guessing. v3 is a new, documented, independently verifiable
 *    algorithm. `closure.json` records the supersession explicitly, and any
 *    consumer of `closure.sha256` must be told which algorithm produced it.
 *
 * 3. CycloneDX 1.6 SBOM (`sbom.cdx.json`)
 *
 *    - Packages are discovered by reading `package.json` under the payload's
 *      `node_modules`, both the top level and the `.pnpm` store layout, with
 *      `@scope/name` handled. Links are read through (never recursed into);
 *      nested real `node_modules` directories are walked with a realpath guard.
 *    - Components are deduplicated by `name@version`, sorted by purl, and
 *      emitted with `type: "library"`, `name`, `version` and
 *      `purl: pkg:npm/%40scope/name@version` ('@' URL-encoded as %40).
 *    - `serialNumber` is a `urn:uuid:` derived deterministically from the slot
 *      closure digest, so re-runs are byte-stable.
 *    - DETERMINISM OF `metadata.timestamp`: this tool is deliberately fully
 *      deterministic. The timestamp is taken from `--timestamp <iso>` if given,
 *      else `TASKHIVE_SBOM_TIMESTAMP` (ISO), else `SOURCE_DATE_EPOCH` (epoch
 *      seconds), else the newest regular-file mtime in the payload (UTC,
 *      seconds precision). The consequence is that `--write` twice produces a
 *      byte-identical `sbom.cdx.json` as well as identical `closure.json` and
 *      `IMMUTABLE`, so the SBOM digest can safely be recorded inside
 *      `closure.json` and used as a gate.
 *
 * USAGE
 * -----------------------------------------------------------------------------
 *   node harness-slot-closure.js [--slot <dir>] [--check | --write]
 *                                [--timestamp <iso8601>] [--help]
 *
 *   default mode            : --check (verify only, writes nothing)
 *   --check (default)       : recompute everything, compare against
 *                             closure.json / IMMUTABLE / sbom.cdx.json, print
 *                             PASS/FAIL per item, exit non-zero on any mismatch
 *   --write                 : write closure.json, sbom.cdx.json, IMMUTABLE
 *   --slot <dir>            : slot directory (default: ../harness/runtime/slot
 *                             relative to this script)
 *   --timestamp <iso8601>   : pin the SBOM metadata timestamp
 *
 * `manifest.json` is NEVER modified. Write mode prints a copy/paste block with
 * the exact keys and values for the release process to put into it.
 *
 * Node standard library only. No network access.
 * =============================================================================
 */
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const GENERATOR_NAME = 'taskhive-harness-slot-closure';
const GENERATOR_VERSION = '1.0.0';

const SLOT_CLOSURE_ALGORITHM = 'taskhive-slot-closure-v3-final-path-links';
const PAYLOAD_ALGORITHM = 'taskhive-payload-content-graph-v1';
const SUPERSEDED_ALGORITHM = 'taskhive-harness-closure-v2-final-path-links';
const SUPERSEDED_NOTE =
  'New, independently defined algorithm. It SUPERSEDES ' +
  SUPERSEDED_ALGORITHM +
  ' but does NOT reproduce it: the v2 generator is absent from this checkout, ' +
  'its row encoding and exclusion set are unknown, and no value produced by this ' +
  'tool may be presented as, or substituted for, a v2 closure of the same tree.';

const CLOSURE_EXCLUSIONS = ['manifest.json', 'closure.json', 'sbom.cdx.json', 'IMMUTABLE'];

const SLOT_CLOSURE_FILENAME = 'closure.json';
const SBOM_FILENAME = 'sbom.cdx.json';
const IMMUTABLE_FILENAME = 'IMMUTABLE';
const MANIFEST_FILENAME = 'manifest.json';
const PAYLOAD_DIRNAME = 'payload';

const DSH_PACKAGE_NAME = '@deepseek-ai/dsh';
const DSH_PACKAGE_REL = ['node_modules', '@deepseek-ai', 'dsh', 'package.json'];

const SBOM_SCHEMA_URL = 'http://cyclonedx.org/schema/bom-1.6.schema.json';

const HASH_CONCURRENCY = 8;
const UNKNOWN_VERSION = '0.0.0-unknown';

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

function toPosix(p) {
  return String(p).replace(/\\/g, '/');
}

function nowIsoSeconds(ms) {
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, 'Z');
}

function sha256HexOfBuffer(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

function sha256HexOfString(str) {
  return sha256HexOfBuffer(Buffer.from(str, 'utf8'));
}

function byteCompare(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function readJsonSafe(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (err) {
    return null;
  }
}

function isDir(abs) {
  try {
    return fs.statSync(abs).isDirectory();
  } catch (err) {
    return false;
  }
}

/** Deterministic RFC-4122-shaped v4 UUID string derived from a hex digest. */
function uuidFromDigest(hex) {
  const h = String(hex).replace(/[^0-9a-fA-F]/g, '').toLowerCase().padEnd(32, '0').slice(0, 32);
  const variant = ((parseInt(h.slice(16, 17), 16) & 0x3) | 0x8).toString(16);
  return [
    h.slice(0, 8),
    h.slice(8, 12),
    '4' + h.slice(13, 16),
    variant + h.slice(17, 20),
    h.slice(20, 32),
  ].join('-');
}

/**
 * Normalize a symlink/junction target so the digest does not carry
 * machine-specific absolute paths when the target lives inside the slot.
 */
function normalizeLinkTarget(rawTarget, slotRootAbs) {
  const raw = toPosix(rawTarget);
  let candidate = raw;
  if (candidate.startsWith('//?/')) candidate = candidate.slice(4);
  if (!path.isAbsolute(candidate)) return raw; // relative target: keep verbatim
  const resolved = toPosix(path.resolve(candidate));
  const slot = toPosix(path.resolve(slotRootAbs));
  const lower = process.platform === 'win32';
  const eq = (a, b) => (lower ? a.toLowerCase() === b.toLowerCase() : a === b);
  const startsWith = (a, b) =>
    lower ? a.toLowerCase().startsWith(b.toLowerCase()) : a.startsWith(b);
  if (eq(resolved, slot)) return '.';
  if (startsWith(resolved, slot + '/')) return './' + resolved.slice(slot.length + 1);
  return raw;
}

// ---------------------------------------------------------------------------
// Payload digest cache: absolute path -> file sha256 (hex)
// ---------------------------------------------------------------------------

const fileHashCache = new Map();

function sha256FileStreaming(abs) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(abs);
    stream.on('error', reject);
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex')));
  });
}

async function fillFileHashes(entries, concurrency) {
  const pending = entries.filter((e) => e.type === 'F' && !fileHashCache.has(e.abs));
  if (pending.length === 0) return;
  let cursor = 0;
  const workers = [];
  const workerCount = Math.max(1, Math.min(concurrency, pending.length));
  for (let i = 0; i < workerCount; i++) {
    workers.push(
      (async () => {
        for (;;) {
          const index = cursor++;
          if (index >= pending.length) return;
          const entry = pending[index];
          fileHashCache.set(entry.abs, await sha256FileStreaming(entry.abs));
        }
      })()
    );
  }
  await Promise.all(workers);
}

// ---------------------------------------------------------------------------
// Tree walk (never descends through symlinks/junctions)
// ---------------------------------------------------------------------------

/**
 * Walk `rootAbs`, recording one entry per filesystem object.
 * Returns { entries, stats } with entries sorted by POSIX relative path.
 */
function walkTree(rootAbs, opts) {
  const options = opts || {};
  const excludeRootNames = options.excludeRootNames || new Set();
  const slotRootAbs = options.slotRootAbs || rootAbs;

  const entries = [];
  const stats = {
    fileCount: 0,
    dirCount: 0,
    linkCount: 0,
    otherCount: 0,
    totalBytes: 0,
    outOfSlotLinkCount: 0,
    maxFileMtimeMs: 0,
    readErrors: [],
  };

  const stack = [{ abs: rootAbs, rel: '' }];
  while (stack.length > 0) {
    const dir = stack.pop();
    let names;
    try {
      names = fs.readdirSync(dir.abs);
    } catch (err) {
      stats.readErrors.push({ path: dir.rel || '.', error: String(err && err.message) });
      continue;
    }
    for (const name of names) {
      const rel = dir.rel ? dir.rel + '/' + name : name;
      if (!dir.rel && excludeRootNames.has(name)) continue;
      const abs = path.join(dir.abs, name);
      let st;
      try {
        st = fs.lstatSync(abs);
      } catch (err) {
        stats.readErrors.push({ path: rel, error: String(err && err.message) });
        continue;
      }

      if (st.isSymbolicLink()) {
        // Record only. Never descend: a junction must not be walked as a tree.
        let rawTarget = '';
        try {
          rawTarget = fs.readlinkSync(abs);
        } catch (err) {
          stats.readErrors.push({ path: rel, error: String(err && err.message) });
        }
        const target = normalizeLinkTarget(rawTarget, slotRootAbs);
        if (target !== '.' && !target.startsWith('./')) stats.outOfSlotLinkCount++;
        entries.push({ rel, type: 'L', target, abs, size: 0 });
        stats.linkCount++;
      } else if (st.isDirectory()) {
        entries.push({ rel, type: 'D', abs, size: 0 });
        stats.dirCount++;
        stack.push({ abs, rel });
      } else {
        const type = st.isFile() ? 'F' : 'O';
        entries.push({ rel, type, abs, size: st.size, mtimeMs: st.mtimeMs });
        if (type === 'F') {
          stats.fileCount++;
          stats.totalBytes += st.size;
          if (st.mtimeMs > stats.maxFileMtimeMs) stats.maxFileMtimeMs = st.mtimeMs;
        } else {
          stats.otherCount++;
        }
      }
    }
  }

  entries.sort((a, b) => byteCompare(a.rel, b.rel));
  return { entries, stats };
}

/** Stream the sorted row encoding of `entries` into sha256. */
async function digestEntries(entries) {
  await fillFileHashes(entries, HASH_CONCURRENCY);
  const hash = crypto.createHash('sha256');
  for (const e of entries) {
    if (e.type === 'F') {
      hash.update('F\0' + e.rel + '\0' + e.size + '\0' + fileHashCache.get(e.abs) + '\n', 'utf8');
    } else if (e.type === 'L') {
      hash.update('L\0' + e.rel + '\0' + e.target + '\n', 'utf8');
    } else if (e.type === 'D') {
      hash.update('D\0' + e.rel + '\n', 'utf8');
    } else {
      hash.update('O\0' + e.rel + '\0' + e.size + '\n', 'utf8');
    }
  }
  return hash.digest('hex');
}

// ---------------------------------------------------------------------------
// SBOM: package discovery
// ---------------------------------------------------------------------------

function recordPackage(pkgDir, acc, source) {
  const manifestPath = path.join(pkgDir, 'package.json');
  const manifest = readJsonSafe(manifestPath);
  if (!manifest || typeof manifest.name !== 'string' || manifest.name.length === 0) {
    acc.skipped.push(toPosix(pkgDir));
    return;
  }
  const name = manifest.name;
  const version =
    typeof manifest.version === 'string' && manifest.version.length > 0
      ? manifest.version
      : UNKNOWN_VERSION;
  if (version === UNKNOWN_VERSION) acc.withoutVersion.push(name);
  const key = name + '@' + version;
  if (acc.byKey.has(key)) return;
  const purlName = name.startsWith('@') ? '%40' + name.slice(1) : name;
  acc.byKey.set(key, {
    type: 'library',
    name,
    version,
    purl: 'pkg:npm/' + purlName + '@' + version,
    sources: [source],
  });
}

/**
 * Scan a `node_modules` directory: real directories are read and (only) their
 * real nested `node_modules` are walked; links are read through but never
 * followed for recursion.
 */
function scanNodeModules(nmDir, acc, visitedRealDirs, depth) {
  if (depth > 8) return;
  let real;
  try {
    real = fs.realpathSync(nmDir);
  } catch (err) {
    return;
  }
  if (visitedRealDirs.has(real)) return;
  visitedRealDirs.add(real);

  let names;
  try {
    names = fs.readdirSync(nmDir);
  } catch (err) {
    return;
  }

  for (const name of names) {
    if (name === '.pnpm') {
      const storeRoot = path.join(nmDir, '.pnpm');
      let storeEntries = [];
      try {
        storeEntries = fs.readdirSync(storeRoot);
      } catch (err) {
        storeEntries = [];
      }
      for (const storeDir of storeEntries) {
        scanNodeModules(path.join(storeRoot, storeDir, 'node_modules'), acc, visitedRealDirs, depth + 1);
      }
      continue;
    }
    if (name === '.bin' || name.charAt(0) === '.') continue;

    const abs = path.join(nmDir, name);
    if (name.charAt(0) === '@') {
      let scoped = [];
      try {
        scoped = fs.readdirSync(abs);
      } catch (err) {
        scoped = [];
      }
      for (const sub of scoped) {
        if (sub.charAt(0) === '.') continue;
        const pkgDir = path.join(abs, sub);
        recordPackage(pkgDir, acc, 'node_modules/' + name + '/' + sub);
        scanNested(pkgDir, acc, visitedRealDirs, depth);
      }
      continue;
    }

    recordPackage(abs, acc, 'node_modules/' + name);
    scanNested(abs, acc, visitedRealDirs, depth);
  }
}

/** Walk a package's own nested node_modules only when it is a real directory. */
function scanNested(pkgDir, acc, visitedRealDirs, depth) {
  let st;
  try {
    st = fs.lstatSync(pkgDir);
  } catch (err) {
    return;
  }
  if (st.isSymbolicLink() || !st.isDirectory()) return; // do not follow links
  const nested = path.join(pkgDir, 'node_modules');
  if (isDir(nested)) scanNodeModules(nested, acc, visitedRealDirs, depth + 1);
}

function collectPackages(nodeModulesDir) {
  const acc = { byKey: new Map(), skipped: [], withoutVersion: [] };
  scanNodeModules(nodeModulesDir, acc, new Set(), 0);
  return acc;
}

// ---------------------------------------------------------------------------
// SBOM: document construction
// ---------------------------------------------------------------------------

function resolveTimestamp(options) {
  if (options.timestamp) {
    const d = new Date(options.timestamp);
    if (Number.isNaN(d.getTime())) {
      throw new Error('--timestamp is not a parseable date: ' + options.timestamp);
    }
    return nowIsoSeconds(d.getTime());
  }
  if (process.env.TASKHIVE_SBOM_TIMESTAMP) {
    const d = new Date(process.env.TASKHIVE_SBOM_TIMESTAMP);
    if (!Number.isNaN(d.getTime())) return nowIsoSeconds(d.getTime());
  }
  if (process.env.SOURCE_DATE_EPOCH) {
    const secs = Number(process.env.SOURCE_DATE_EPOCH);
    if (Number.isFinite(secs)) return nowIsoSeconds(secs * 1000);
  }
  return nowIsoSeconds(options.fallbackMtimeMs || Date.now());
}

function buildSbom(options) {
  const components = Array.from(options.packages.byKey.values())
    .map((c) => ({ type: c.type, name: c.name, version: c.version, purl: c.purl }))
    .sort((a, b) => byteCompare(a.purl, b.purl));

  const dshVersion = options.dshVersion || UNKNOWN_VERSION;
  const serialUuid = uuidFromDigest(options.closureDigest);

  const doc = {
    $schema: SBOM_SCHEMA_URL,
    bomFormat: 'CycloneDX',
    specVersion: '1.6',
    serialNumber: 'urn:uuid:' + serialUuid,
    version: 1,
    metadata: {
      timestamp: options.timestamp,
      tools: {
        components: [
          {
            type: 'application',
            name: GENERATOR_NAME,
            version: GENERATOR_VERSION,
            purl: 'pkg:npm/' + GENERATOR_NAME + '@' + GENERATOR_VERSION,
          },
        ],
      },
      component: {
        type: 'application',
        name: DSH_PACKAGE_NAME,
        version: dshVersion,
        purl: 'pkg:npm/%40deepseek-ai/dsh@' + dshVersion,
        description: 'DeepSeek Harness runtime embedded in the TaskHive Electron app (slot payload).',
      },
      properties: [
        { name: 'taskhive:slot.closure.algorithm', value: SLOT_CLOSURE_ALGORITHM },
        { name: 'taskhive:slot.closure.sha256', value: options.closureDigest },
        { name: 'taskhive:payload.contentGraph.algorithm', value: PAYLOAD_ALGORITHM },
        { name: 'taskhive:payload.contentGraph.sha256', value: options.payloadDigest },
        { name: 'taskhive:sbom.timestamp.source', value: options.timestampSource },
        {
          name: 'taskhive:sbom.discovery.rule',
          value:
            'A component is a directory that sits inside a node_modules directory (top level, the ' +
            '.pnpm virtual store, or a real nested node_modules) and contains a parseable ' +
            'package.json with name and version. Symlinks/junctions are read through but never ' +
            'traversed. package.json manifests that are not inside any node_modules directory ' +
            '(for example nan/tools/package.json and fast-uri/benchmark/package.json in this ' +
            'payload) are fixtures, not installed packages, and are deliberately not components.',
        },
        { name: 'taskhive:sbom.componentCount', value: String(components.length) },
        { name: 'taskhive:sbom.serialNumber.derivation', value: 'urn:uuid derived from the slot closure sha256 (deterministic)' },
      ],
    },
    components,
  };

  return { doc, components };
}

// ---------------------------------------------------------------------------
// Measurement pipeline
// ---------------------------------------------------------------------------

async function measure(slotDir, options) {
  const slotRootAbs = path.resolve(slotDir);
  const payloadAbs = path.join(slotRootAbs, PAYLOAD_DIRNAME);

  if (!isDir(slotRootAbs)) throw new Error('slot directory not found: ' + slotRootAbs);
  if (!isDir(payloadAbs)) throw new Error('payload directory not found: ' + payloadAbs);

  // 1. payload tree + payload content digest
  const payloadWalk = walkTree(payloadAbs, { slotRootAbs });
  const payloadDigest = await digestEntries(payloadWalk.entries);

  // 2. whole-slot closure digest (this tool's generated files excluded)
  const slotWalk = walkTree(slotRootAbs, {
    slotRootAbs,
    excludeRootNames: new Set(CLOSURE_EXCLUSIONS),
  });
  const closureDigest = await digestEntries(slotWalk.entries);

  // 3. SBOM from what is actually installed
  const nodeModulesDir = path.join(payloadAbs, 'node_modules');
  const packages = collectPackages(nodeModulesDir);

  const dshManifest = readJsonSafe(path.join(payloadAbs, ...DSH_PACKAGE_REL));
  const dshVersion =
    dshManifest && typeof dshManifest.version === 'string' ? dshManifest.version : null;

  const timestampSource = options.timestamp
    ? 'cli:--timestamp'
    : process.env.TASKHIVE_SBOM_TIMESTAMP
      ? 'env:TASKHIVE_SBOM_TIMESTAMP'
      : process.env.SOURCE_DATE_EPOCH
        ? 'env:SOURCE_DATE_EPOCH'
        : 'payload-max-file-mtime';
  const timestamp = resolveTimestamp({
    timestamp: options.timestamp,
    fallbackMtimeMs: payloadWalk.stats.maxFileMtimeMs,
  });

  const sbom = buildSbom({
    packages,
    dshVersion,
    closureDigest,
    payloadDigest,
    timestamp,
    timestampSource,
  });
  const sbomText = JSON.stringify(sbom.doc, null, 2) + '\n';
  const sbomDigest = sha256HexOfString(sbomText);

  const result = {
    schemaVersion: 1,
    generator: { name: GENERATOR_NAME, version: GENERATOR_VERSION },
    slot: { path: '.', payloadPath: PAYLOAD_DIRNAME },
    closure: {
      algorithm: SLOT_CLOSURE_ALGORITHM,
      description:
        'sha256 over the sorted "F/D/L/O" row encoding (NUL-separated, LF-terminated; files ' +
        'contribute size plus their own streamed sha256, links contribute their normalized ' +
        'target) of every entry in the slot tree, relative paths POSIX, sorted by path, ' +
        'excluding ' + CLOSURE_EXCLUSIONS.join(', ') + '.',
      supersedes: {
        algorithm: SUPERSEDED_ALGORITHM,
        reproducibleInThisCheckout: false,
        note: SUPERSEDED_NOTE,
      },
      excludedPaths: CLOSURE_EXCLUSIONS.slice(),
      sha256: closureDigest,
    },
    payload: {
      path: PAYLOAD_DIRNAME,
      algorithm: PAYLOAD_ALGORITHM,
      description:
        'Same row encoding and sort order as the slot closure digest, rooted at <slot>/payload; ' +
        'excludes nothing.',
      sha256: payloadDigest,
      fileCount: payloadWalk.stats.fileCount,
      totalBytes: payloadWalk.stats.totalBytes,
      linkCount: payloadWalk.stats.linkCount,
      dirCount: payloadWalk.stats.dirCount,
      otherCount: payloadWalk.stats.otherCount,
    },
    sbom: {
      path: SBOM_FILENAME,
      format: 'CycloneDX',
      specVersion: '1.6',
      sha256: sbomDigest,
      serialNumber: sbom.doc.serialNumber,
      componentCount: sbom.components.length,
      timestamp,
    },
    dsh: { name: DSH_PACKAGE_NAME, version: dshVersion },
  };

  return {
    slotRootAbs,
    payloadAbs,
    result,
    payloadWalk,
    slotWalk,
    sbom,
    sbomText,
    sbomDigest,
    packages,
    dshVersion,
  };
}

// ---------------------------------------------------------------------------
// Check
// ---------------------------------------------------------------------------

function runChecks(m, stored) {
  const checks = [];
  const add = (label, ok, detail) => checks.push({ label, ok: !!ok, detail: detail || '' });
  const r = m.result;

  add(
    'closure.json present and parseable',
    !!stored,
    stored ? '' : 'missing or invalid JSON at ' + SLOT_CLOSURE_FILENAME + ' (run --write)'
  );
  if (!stored) return checks;

  add(
    'closure.algorithm is ' + SLOT_CLOSURE_ALGORITHM,
    stored.closure && stored.closure.algorithm === SLOT_CLOSURE_ALGORITHM,
    'stored=' + JSON.stringify(stored.closure && stored.closure.algorithm)
  );
  add(
    'closure.supersedes names ' + SUPERSEDED_ALGORITHM + ' as not reproducible here',
    !!(stored.closure && stored.closure.supersedes &&
      stored.closure.supersedes.algorithm === SUPERSEDED_ALGORITHM &&
      stored.closure.supersedes.reproducibleInThisCheckout === false),
    'stored=' + JSON.stringify(stored.closure && stored.closure.supersedes)
  );

  const exStored = (stored.closure && stored.closure.excludedPaths) || [];
  add(
    'closure.excludedPaths matches [' + CLOSURE_EXCLUSIONS.join(', ') + ']',
    exStored.length === CLOSURE_EXCLUSIONS.length &&
      CLOSURE_EXCLUSIONS.every((n) => exStored.indexOf(n) !== -1),
    'stored=' + JSON.stringify(exStored)
  );

  const pc = (stored.payload || {});
  add('payload.fileCount', pc.fileCount === r.payload.fileCount, 'stored=' + pc.fileCount + ' computed=' + r.payload.fileCount);
  add('payload.totalBytes', pc.totalBytes === r.payload.totalBytes, 'stored=' + pc.totalBytes + ' computed=' + r.payload.totalBytes);
  add('payload.linkCount', pc.linkCount === r.payload.linkCount, 'stored=' + pc.linkCount + ' computed=' + r.payload.linkCount);
  add('payload.dirCount', pc.dirCount === r.payload.dirCount, 'stored=' + pc.dirCount + ' computed=' + r.payload.dirCount);
  add('payload.sha256 (' + PAYLOAD_ALGORITHM + ')', pc.sha256 === r.payload.sha256, 'stored=' + pc.sha256 + ' computed=' + r.payload.sha256);
  add(
    'closure.sha256 (' + SLOT_CLOSURE_ALGORITHM + ')',
    stored.closure.sha256 === r.closure.sha256,
    'stored=' + stored.closure.sha256 + ' computed=' + r.closure.sha256
  );

  // IMMUTABLE
  let immText = null;
  try {
    immText = fs.readFileSync(path.join(m.slotRootAbs, IMMUTABLE_FILENAME), 'utf8').trim();
  } catch (err) {
    immText = null;
  }
  add(
    IMMUTABLE_FILENAME + ' matches closure.sha256',
    immText === r.closure.sha256,
    immText === null ? 'missing' : 'file=' + immText + ' computed=' + r.closure.sha256
  );

  // SBOM file digest
  let sbomOnDiskDigest = null;
  let sbomDoc = null;
  try {
    const buf = fs.readFileSync(path.join(m.slotRootAbs, SBOM_FILENAME));
    sbomOnDiskDigest = sha256HexOfBuffer(buf);
    sbomDoc = JSON.parse(buf.toString('utf8'));
  } catch (err) {
    sbomOnDiskDigest = null;
  }
  add(
    SBOM_FILENAME + ' digest matches closure.json sbom.sha256',
    sbomOnDiskDigest !== null && stored.sbom && sbomOnDiskDigest === stored.sbom.sha256,
    sbomOnDiskDigest === null
      ? 'missing or unparseable'
      : 'file=' + sbomOnDiskDigest + ' stored=' + (stored.sbom && stored.sbom.sha256)
  );
  add(
    SBOM_FILENAME + ' digest matches freshly generated SBOM',
    sbomOnDiskDigest !== null && sbomOnDiskDigest === m.sbomDigest,
    sbomOnDiskDigest === null ? 'missing' : 'file=' + sbomOnDiskDigest + ' computed=' + m.sbomDigest
  );

  if (sbomDoc) {
    add('sbom.bomFormat is CycloneDX', sbomDoc.bomFormat === 'CycloneDX', 'file=' + JSON.stringify(sbomDoc.bomFormat));
    add('sbom.specVersion is 1.6', sbomDoc.specVersion === '1.6', 'file=' + JSON.stringify(sbomDoc.specVersion));
    add(
      'sbom.serialNumber matches derived urn:uuid',
      sbomDoc.serialNumber === r.sbom.serialNumber,
      'file=' + sbomDoc.serialNumber + ' computed=' + r.sbom.serialNumber
    );
    add(
      'sbom.components count matches recomputed package set',
      Array.isArray(sbomDoc.components) && sbomDoc.components.length === m.sbom.components.length,
      'file=' + (Array.isArray(sbomDoc.components) ? sbomDoc.components.length : 'n/a') +
        ' computed=' + m.sbom.components.length
    );
    add(
      'sbom.metadata.component is ' + DSH_PACKAGE_NAME + '@' + r.dsh.version,
      !!(sbomDoc.metadata && sbomDoc.metadata.component &&
        sbomDoc.metadata.component.name === DSH_PACKAGE_NAME &&
        sbomDoc.metadata.component.version === m.dshVersion),
      'file=' + JSON.stringify(sbomDoc.metadata && sbomDoc.metadata.component)
    );
    const sortedOk =
      Array.isArray(sbomDoc.components) &&
      sbomDoc.components.every((c, i, arr) => i === 0 || byteCompare(arr[i - 1].purl, c.purl) <= 0);
    add('sbom.components sorted by purl', sortedOk, '');
  } else {
    add('sbom document parseable', false, 'missing or invalid JSON');
  }

  add(
    'sbom.componentCount recorded in closure.json',
    stored.sbom && stored.sbom.componentCount === r.sbom.componentCount,
    'stored=' + (stored.sbom && stored.sbom.componentCount) + ' computed=' + r.sbom.componentCount
  );
  add(
    'dsh version matches closure.json',
    stored.dsh && stored.dsh.version === r.dsh.version,
    'stored=' + (stored.dsh && stored.dsh.version) + ' computed=' + r.dsh.version
  );

  return checks;
}

// ---------------------------------------------------------------------------
// Reporting
// ---------------------------------------------------------------------------

function printManifestBlock(m) {
  const r = m.result;
  const fragment = {
    closure: {
      algorithm: SLOT_CLOSURE_ALGORITHM,
      sha256: r.closure.sha256,
      supersedes: SUPERSEDED_ALGORITHM,
    },
    payload: {
      sha256: r.payload.sha256,
      fileCount: r.payload.fileCount,
      totalBytes: r.payload.totalBytes,
      linkCount: r.payload.linkCount,
      contentGraph: {
        algorithm: PAYLOAD_ALGORITHM,
        sha256: r.payload.sha256,
      },
    },
    sbom: {
      format: 'CycloneDX',
      specVersion: '1.6',
      path: SBOM_FILENAME,
      sha256: r.sbom.sha256,
      componentCount: r.sbom.componentCount,
      stale: false,
    },
  };

  console.log('');
  console.log('=== manifest.json PASTE BLOCK (this tool does NOT write manifest.json) ===');
  console.log('closure.sha256        = ' + r.closure.sha256);
  console.log('payload.sha256        = ' + r.payload.sha256);
  console.log('payload.fileCount     = ' + r.payload.fileCount);
  console.log('payload.totalBytes    = ' + r.payload.totalBytes);
  console.log('payload.linkCount     = ' + r.payload.linkCount);
  console.log('sbom.sha256           = ' + r.sbom.sha256);
  console.log('');
  console.log('JSON fragment:');
  console.log(JSON.stringify(fragment, null, 2));
  console.log('');
  console.log('Also required, because the recorded algorithm/digest pair changes:');
  console.log('  closure.algorithm        -> "' + SLOT_CLOSURE_ALGORITHM + '"');
  console.log('  closure.pendingReason    -> remove (closure is now computed)');
  console.log('  sbom.stale / staleReason -> set false / remove');
  console.log('  note: closure.algorithm must NOT stay "' + SUPERSEDED_ALGORITHM + '";');
  console.log('        v3 supersedes v2 and does not reproduce its value.');
  console.log('=== end manifest.json PASTE BLOCK ===');
}

function manifestAdvisory(m) {
  const manifest = readJsonSafe(path.join(m.slotRootAbs, MANIFEST_FILENAME));
  if (!manifest) return;
  const r = m.result;
  const lines = [];
  const cl = manifest.closure || {};
  const pl = manifest.payload || {};
  const sb = manifest.sbom || {};
  if (cl.sha256 !== r.closure.sha256) {
    lines.push(
      '  closure.sha256: manifest=' + JSON.stringify(cl.sha256) + ' expected=' + r.closure.sha256
    );
  }
  if (cl.algorithm !== SLOT_CLOSURE_ALGORITHM) {
    lines.push('  closure.algorithm: manifest=' + JSON.stringify(cl.algorithm) + ' expected=' + SLOT_CLOSURE_ALGORITHM);
  }
  for (const key of ['fileCount', 'totalBytes', 'linkCount']) {
    if (pl[key] !== r.payload[key]) {
      lines.push('  payload.' + key + ': manifest=' + pl[key] + ' measured=' + r.payload[key]);
    }
  }
  if (pl.sha256 !== r.payload.sha256) {
    lines.push('  payload.sha256: manifest=' + JSON.stringify(pl.sha256) + ' measured=' + r.payload.sha256);
  }
  if (pl.contentGraph && pl.contentGraph.sha256 !== r.payload.sha256) {
    lines.push(
      '  payload.contentGraph.sha256: manifest=' + JSON.stringify(pl.contentGraph.sha256) +
        ' measured=' + r.payload.sha256 + ' (recorded under a different, loosely specified format)'
    );
  }
  if (sb.sha256 !== r.sbom.sha256) {
    lines.push('  sbom.sha256: manifest=' + JSON.stringify(sb.sha256) + ' generated=' + r.sbom.sha256);
  }
  if (lines.length === 0) return;
  console.log('');
  console.log('--- manifest.json advisory (informational only; manifest.json is parent-owned and was NOT written) ---');
  for (const line of lines) console.log(line);
}

function printSummary(m, mode) {
  const r = m.result;
  console.log('');
  console.log('=== harness slot closure summary (' + mode + ') ===');
  console.log('slot                : ' + m.slotRootAbs);
  console.log('payload             : ' + r.payload.path);
  console.log('closure algorithm   : ' + r.closure.algorithm);
  console.log('closure sha256      : ' + r.closure.sha256);
  console.log('  (supersedes ' + SUPERSEDED_ALGORITHM + '; NOT a reproduction of it)');
  console.log('payload algorithm   : ' + r.payload.algorithm);
  console.log('payload sha256      : ' + r.payload.sha256);
  console.log('payload fileCount   : ' + r.payload.fileCount);
  console.log('payload totalBytes  : ' + r.payload.totalBytes + ' (' + (r.payload.totalBytes / 1048576).toFixed(1) + ' MiB)');
  console.log('payload linkCount   : ' + r.payload.linkCount);
  console.log('payload dirCount    : ' + r.payload.dirCount);
  console.log('payload otherCount  : ' + r.payload.otherCount);
  console.log('out-of-slot links   : ' + m.payloadWalk.stats.outOfSlotLinkCount +
    (m.payloadWalk.stats.outOfSlotLinkCount > 0 ? '  <-- link targets outside the slot are hashed verbatim (machine-specific)' : ''));
  console.log('slot entries hashed : ' + m.slotWalk.entries.length);
  console.log('dsh version         : ' + (m.dshVersion || 'NOT FOUND'));
  console.log('sbom                : ' + r.sbom.path + '  CycloneDX ' + r.sbom.specVersion);
  console.log('sbom components     : ' + r.sbom.componentCount);
  console.log('sbom serialNumber   : ' + r.sbom.serialNumber);
  console.log('sbom timestamp      : ' + r.sbom.timestamp);
  console.log('sbom sha256         : ' + r.sbom.sha256);
  if (m.packages.skipped.length > 0) {
    console.log('sbom packages skipped (no name in package.json): ' + m.packages.skipped.length);
  }
  if (m.payloadWalk.stats.readErrors.length > 0) {
    console.log('payload read errors : ' + m.payloadWalk.stats.readErrors.length);
    for (const e of m.payloadWalk.stats.readErrors.slice(0, 5)) console.log('  ' + e.path + ': ' + e.error);
  }
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const defaultSlot = path.resolve(__dirname, '..', 'harness', 'runtime', 'slot');
  const opts = { slot: defaultSlot, mode: 'check', timestamp: null, help: false };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--slot') {
      const value = argv[++i];
      if (!value) throw new Error('--slot requires a path');
      opts.slot = path.resolve(value);
    } else if (arg === '--write') {
      if (opts.mode === 'check' && argv.indexOf('--check') !== -1) {
        throw new Error('--check and --write are mutually exclusive');
      }
      opts.mode = 'write';
    } else if (arg === '--check') {
      if (opts.mode === 'write') throw new Error('--check and --write are mutually exclusive');
      opts.mode = 'check';
    } else if (arg === '--timestamp') {
      const value = argv[++i];
      if (!value) throw new Error('--timestamp requires an ISO-8601 value');
      opts.timestamp = value;
    } else if (arg === '--help' || arg === '-h') {
      opts.help = true;
    } else {
      throw new Error('unknown argument: ' + arg);
    }
  }
  return opts;
}

function usage() {
  console.log('usage: node harness-slot-closure.js [--slot <dir>] [--check | --write] [--timestamp <iso8601>]');
  console.log('');
  console.log('  --check (default)  verify closure.json / IMMUTABLE / sbom.cdx.json against a fresh recomputation');
  console.log('  --write            write closure.json, sbom.cdx.json and IMMUTABLE (never manifest.json)');
  console.log('  --slot <dir>       slot directory (default: ../harness/runtime/slot next to this script)');
}

async function main() {
  let opts;
  try {
    opts = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error('error: ' + err.message);
    usage();
    process.exitCode = 2;
    return;
  }
  if (opts.help) {
    usage();
    return;
  }

  const started = Date.now();
  let m;
  try {
    m = await measure(opts.slot, opts);
  } catch (err) {
    console.error('error: ' + err.message);
    process.exitCode = 2;
    return;
  }

  const closurePath = path.join(m.slotRootAbs, SLOT_CLOSURE_FILENAME);

  if (opts.mode === 'write') {
    const before = readJsonSafe(closurePath);
    const immutableBefore = (() => {
      try {
        return fs.readFileSync(path.join(m.slotRootAbs, IMMUTABLE_FILENAME), 'utf8').trim();
      } catch (err) {
        return null;
      }
    })();
    const sbomBefore = (() => {
      try {
        return sha256HexOfBuffer(fs.readFileSync(path.join(m.slotRootAbs, SBOM_FILENAME)));
      } catch (err) {
        return null;
      }
    })();

    fs.writeFileSync(path.join(m.slotRootAbs, SBOM_FILENAME), m.sbomText, 'utf8');
    fs.writeFileSync(closurePath, JSON.stringify(m.result, null, 2) + '\n', 'utf8');
    fs.writeFileSync(path.join(m.slotRootAbs, IMMUTABLE_FILENAME), m.result.closure.sha256 + '\n', 'utf8');

    console.log('wrote ' + SLOT_CLOSURE_FILENAME + ', ' + SBOM_FILENAME + ', ' + IMMUTABLE_FILENAME);
    console.log('');
    console.log('idempotence vs previous on-disk state:');
    console.log('  closure.json : ' + (before
      ? (before.closure && before.closure.sha256 === m.result.closure.sha256 &&
         before.payload && before.payload.sha256 === m.result.payload.sha256
        ? 'IDENTICAL closure+payload digests to previous run'
        : 'CHANGED from previous run (previous closure.sha256=' +
          (before.closure && before.closure.sha256) + ')')
      : 'no previous closure.json'));
    console.log('  IMMUTABLE    : ' + (immutableBefore === null
      ? 'no previous file'
      : immutableBefore === m.result.closure.sha256
        ? 'IDENTICAL (' + immutableBefore + ')'
        : 'CHANGED (previous=' + immutableBefore + ', now=' + m.result.closure.sha256 + ')'));
    console.log('  sbom.cdx.json: ' + (sbomBefore === null
      ? 'no previous file'
      : sbomBefore === m.sbomDigest
        ? 'IDENTICAL (' + sbomBefore + ')'
        : 'CHANGED (previous=' + sbomBefore + ', now=' + m.sbomDigest + ')'));

    // Read back and verify what was just written.
    const stored = readJsonSafe(closurePath);
    const checks = runChecks(m, stored);
    const failed = checks.filter((c) => !c.ok);
    console.log('');
    console.log('post-write verification: ' + (failed.length === 0 ? 'PASS' : 'FAIL'));
    for (const c of checks) {
      console.log('  [' + (c.ok ? 'PASS' : 'FAIL') + '] ' + c.label + (c.detail ? '  (' + c.detail + ')' : ''));
    }
    printSummary(m, 'write');
    printManifestBlock(m);
    manifestAdvisory(m);
    console.log('');
    console.log('elapsed: ' + ((Date.now() - started) / 1000).toFixed(1) + ' s');
    if (failed.length > 0) process.exitCode = 1;
    return;
  }

  // check mode
  const stored = readJsonSafe(closurePath);
  const checks = runChecks(m, stored);
  const failed = checks.filter((c) => !c.ok);
  console.log('=== harness slot closure check ===');
  console.log('slot: ' + m.slotRootAbs);
  console.log('');
  for (const c of checks) {
    console.log('[' + (c.ok ? 'PASS' : 'FAIL') + '] ' + c.label + (c.detail ? '  (' + c.detail + ')' : ''));
  }
  console.log('');
  console.log('result: ' + (failed.length === 0 ? 'PASS' : 'FAIL (' + failed.length + '/' + checks.length + ' checks failed)'));
  printSummary(m, 'check');
  printManifestBlock(m);
  manifestAdvisory(m);
  console.log('');
  console.log('elapsed: ' + ((Date.now() - started) / 1000).toFixed(1) + ' s');
  if (failed.length > 0) process.exitCode = 1;
}

main().catch((err) => {
  console.error('unexpected error: ' + (err && err.stack ? err.stack : err));
  process.exitCode = 2;
});
